import{_ as t,o as a,c as e,a2 as r}from"./chunks/framework.DaAAbehN.js";const p=JSON.parse('{"title":"第 2 课：Codex 能帮你做什么？（展示环节）","description":"","frontmatter":{},"headers":[],"relativePath":"modules/module-1/lesson-2.md","filePath":"modules/module-1/lesson-2.md"}'),l={name:"modules/module-1/lesson-2.md"};function i(d,o,n,s,h,u){return a(),e("div",null,[...o[0]||(o[0]=[r('<h1 id="第-2-课-codex-能帮你做什么-展示环节" tabindex="-1">第 2 课：Codex 能帮你做什么？（展示环节） <a class="header-anchor" href="#第-2-课-codex-能帮你做什么-展示环节" aria-label="Permalink to &quot;第 2 课：Codex 能帮你做什么？（展示环节）&quot;">​</a></h1><blockquote><p>📌 <strong>学习目标</strong>：通过实际案例了解 Codex 的能力边界和应用场景<br> ⏱️ <strong>预计时长</strong>：20 分钟<br> 🎯 <strong>本节节奏</strong>：纯演示为主，边看边聊</p></blockquote><hr><h2 id="一、开场-先看看-codex-到底有多-能干" tabindex="-1">一、开场：先看看 Codex 到底有多&quot;能干&quot; <a class="header-anchor" href="#一、开场-先看看-codex-到底有多-能干" aria-label="Permalink to &quot;一、开场：先看看 Codex 到底有多&quot;能干&quot;&quot;">​</a></h2><p>在正式学之前，我想先给你看几个真实案例。这些不是&quot;演示用的小把戏&quot;，而是普通人真的在用 Codex 完成的工作。</p><hr><h2 id="二、编程开发-不只是写代码" tabindex="-1">二、编程开发：不只是写代码 <a class="header-anchor" href="#二、编程开发-不只是写代码" aria-label="Permalink to &quot;二、编程开发：不只是写代码&quot;">​</a></h2><h3 id="案例-1-修一个-bug" tabindex="-1">案例 1：修一个 Bug <a class="header-anchor" href="#案例-1-修一个-bug" aria-label="Permalink to &quot;案例 1：修一个 Bug&quot;">​</a></h3><p><strong>学员背景</strong>：小王，大学生，做课程项目时遇到一个 Python 报错，查了两天没解决。</p><p><strong>他怎么做的</strong>：</p><ol><li>把报错信息复制给 Codex</li><li>把相关代码文件拖进 Codex 工作区</li><li>说：&quot;这个函数报 &#39;IndexError: list index out of range&#39;，帮我找原因并修复&quot;</li></ol><p><strong>结果</strong>：Codex 在 30 秒内找到了问题——列表索引越界，因为代码没有检查列表是否为空。它给出了修复后的代码，还解释了为什么出错。</p><blockquote><p>💡 <strong>关键点</strong>：你不需要知道什么是&quot;索引越界&quot;，你只需要告诉 Codex &quot;出错了，帮我修&quot;。</p></blockquote><h3 id="案例-2-从一个想法到完整网页" tabindex="-1">案例 2：从一个想法到完整网页 <a class="header-anchor" href="#案例-2-从一个想法到完整网页" aria-label="Permalink to &quot;案例 2：从一个想法到完整网页&quot;">​</a></h3><p><strong>学员背景</strong>：小李，市场专员，想做一个产品宣传页，但不会前端开发。</p><p><strong>他怎么做的</strong>：</p><ol><li>打开 Codex，说：&quot;帮我做一个单页网站，介绍我的产品——一款智能水杯&quot;</li><li>Codex 生成了一个包含 Hero 区域、功能介绍、用户评价的完整 HTML 页面</li><li>小李说：&quot;把主色调改成蓝色，加一个联系表单&quot;</li><li>Codex 修改后，小李把文件保存为 <code>index.html</code>，双击就能在浏览器里看</li></ol><p><strong>结果</strong>：一个原本需要花几天时间的前端工作，30 分钟搞定。</p><h3 id="案例-3-重构一段混乱的代码" tabindex="-1">案例 3：重构一段混乱的代码 <a class="header-anchor" href="#案例-3-重构一段混乱的代码" aria-label="Permalink to &quot;案例 3：重构一段混乱的代码&quot;">​</a></h3><p><strong>学员背景</strong>：老张，运维工程师，接手了一段前任写的 Python 脚本，代码又长又乱。</p><p><strong>他怎么做的</strong>：</p><ol><li>把文件拖进 Codex</li><li>说：&quot;这段代码太乱了，帮我重构一下，加上注释，让其他人也能看懂&quot;</li></ol><p><strong>结果</strong>：Codex 把代码拆成了清晰的函数，加了文档字符串，还写了使用说明。</p><hr><h2 id="三、办公提效-整理资料、生成内容" tabindex="-1">三、办公提效：整理资料、生成内容 <a class="header-anchor" href="#三、办公提效-整理资料、生成内容" aria-label="Permalink to &quot;三、办公提效：整理资料、生成内容&quot;">​</a></h2><h3 id="案例-4-整理杂乱的下载文件夹" tabindex="-1">案例 4：整理杂乱的下载文件夹 <a class="header-anchor" href="#案例-4-整理杂乱的下载文件夹" aria-label="Permalink to &quot;案例 4：整理杂乱的下载文件夹&quot;">​</a></h3><p><strong>学员背景</strong>：小陈，行政人员，电脑&quot;下载&quot;文件夹里有几百个文件，乱七八糟。</p><p><strong>她怎么做的</strong>：</p><ol><li>把&quot;下载&quot;文件夹设为 Codex 的工作区</li><li>说：&quot;帮我整理这个文件夹，按文件类型分类，图片放 images 文件夹，PDF 放 documents，Excel 放 spreadsheets&quot;</li><li>Codex 自动创建了子文件夹，把文件移了进去</li></ol><p><strong>结果</strong>：5 分钟，一个混乱的文件夹变得井井有条。</p><h3 id="案例-5-生成会议纪要" tabindex="-1">案例 5：生成会议纪要 <a class="header-anchor" href="#案例-5-生成会议纪要" aria-label="Permalink to &quot;案例 5：生成会议纪要&quot;">​</a></h3><p><strong>学员背景</strong>：阿杰，项目经理，每天开各种会，纪要写得头疼。</p><p><strong>他怎么做的</strong>：</p><ol><li>把会议录音转成的文字稿（或语音转文字后的文本）发给 Codex</li><li>说：&quot;根据这份会议记录，生成一份结构化的会议纪要，包括：议题、讨论要点、决议事项、待办任务（含责任人）&quot;</li></ol><p><strong>结果</strong>：Codex 生成了一份格式清晰的会议纪要，比他自己写的还规范。</p><h3 id="案例-6-批量处理-excel-数据" tabindex="-1">案例 6：批量处理 Excel 数据 <a class="header-anchor" href="#案例-6-批量处理-excel-数据" aria-label="Permalink to &quot;案例 6：批量处理 Excel 数据&quot;">​</a></h3><p><strong>学员背景</strong>：小刘，财务分析师，每个月要做销售报表。</p><p><strong>他怎么做的</strong>：</p><ol><li>把 Excel 文件拖进 Codex</li><li>说：&quot;分析这份销售数据，找出每个产品的月度趋势，生成一个汇总报告&quot;</li><li>Codex 用 Python 读取了 Excel，做了数据分析，生成了图表</li></ol><p><strong>结果</strong>：原本需要 2 小时的手工工作，5 分钟完成。</p><hr><h2 id="四、数据分析-自动化处理-生成报告" tabindex="-1">四、数据分析：自动化处理 + 生成报告 <a class="header-anchor" href="#四、数据分析-自动化处理-生成报告" aria-label="Permalink to &quot;四、数据分析：自动化处理 + 生成报告&quot;">​</a></h2><h3 id="案例-7-从-csv-到可视化报告" tabindex="-1">案例 7：从 CSV 到可视化报告 <a class="header-anchor" href="#案例-7-从-csv-到可视化报告" aria-label="Permalink to &quot;案例 7：从 CSV 到可视化报告&quot;">​</a></h3><p><strong>学员背景</strong>：小周，自媒体运营，需要从后台导出数据并做分析。</p><p><strong>他怎么做的</strong>：</p><ol><li>导出后台数据的 CSV 文件</li><li>拖进 Codex，说：&quot;分析这些数据，告诉我哪篇文章阅读量最高，哪些时间段发布效果最好&quot;</li><li>Codex 生成了分析结论和可视化图表</li></ol><h3 id="案例-8-对比两个数据集" tabindex="-1">案例 8：对比两个数据集 <a class="header-anchor" href="#案例-8-对比两个数据集" aria-label="Permalink to &quot;案例 8：对比两个数据集&quot;">​</a></h3><p><strong>学员背景</strong>：老李，电商运营，需要对比两个季度的销售数据。</p><p><strong>他怎么做的</strong>：</p><ol><li>把两个季度的 CSV 文件都拖进 Codex</li><li>说：&quot;对比这两个文件，找出增长最快的品类和下降最快的品类&quot;</li><li>Codex 完成了对比，生成了结论</li></ol><hr><h2 id="五、日常任务-不只是-专业-场景" tabindex="-1">五、日常任务：不只是&quot;专业&quot;场景 <a class="header-anchor" href="#五、日常任务-不只是-专业-场景" aria-label="Permalink to &quot;五、日常任务：不只是&quot;专业&quot;场景&quot;">​</a></h2><h3 id="案例-9-整理照片" tabindex="-1">案例 9：整理照片 <a class="header-anchor" href="#案例-9-整理照片" aria-label="Permalink to &quot;案例 9：整理照片&quot;">​</a></h3><p><strong>学员背景</strong>：小吴，摄影师爱好者，手机里几千张照片不知道该怎么分类。</p><p><strong>他怎么做的</strong>：</p><ol><li>把照片文件夹拖进 Codex</li><li>说：&quot;按拍摄日期把这些照片分成不同的文件夹，每个月一个&quot;</li><li>Codex 读取了照片的 EXIF 信息，按日期分类</li></ol><h3 id="案例-10-分析磁盘空间" tabindex="-1">案例 10：分析磁盘空间 <a class="header-anchor" href="#案例-10-分析磁盘空间" aria-label="Permalink to &quot;案例 10：分析磁盘空间&quot;">​</a></h3><p><strong>学员背景</strong>：老赵，电脑快满了，想知道是什么占用了空间。</p><p><strong>他怎么做的</strong>：</p><ol><li>说：&quot;帮我分析一下这个文件夹的空间占用情况，列出最大的 10 个文件&quot;</li><li>Codex 执行了系统命令，生成了分析报告</li></ol><h3 id="案例-11-翻译和润色文档" tabindex="-1">案例 11：翻译和润色文档 <a class="header-anchor" href="#案例-11-翻译和润色文档" aria-label="Permalink to &quot;案例 11：翻译和润色文档&quot;">​</a></h3><p><strong>学员背景</strong>：小郑，需要把一份中文报告翻译成英文。</p><p><strong>他怎么做的</strong>：</p><ol><li>把文档拖进 Codex</li><li>说：&quot;把这份中文报告翻译成英文，保持正式商务风格&quot;</li></ol><hr><h2 id="六、非技术人员也在用" tabindex="-1">六、非技术人员也在用 <a class="header-anchor" href="#六、非技术人员也在用" aria-label="Permalink to &quot;六、非技术人员也在用&quot;">​</a></h2><p>这里有一个你可能不知道的真相：<strong>OpenAI 内部，非技术岗位的人也在用 Codex 工作。</strong></p><table tabindex="0"><thead><tr><th>岗位</th><th>使用场景</th></tr></thead><tbody><tr><td>律师</td><td>整理合同条款、提取关键日期和金额</td></tr><tr><td>招聘人员</td><td>筛选简历、生成面试问题</td></tr><tr><td>运营</td><td>分析用户反馈数据、生成周报</td></tr><tr><td>设计师</td><td>生成 CSS 样式、调整设计稿的参数</td></tr><tr><td>教师</td><td>出题、批改作业、生成教学材料</td></tr></tbody></table><p><strong>这意味着什么？</strong> 意味着 Codex 不是&quot;程序员专属工具&quot;，它是&quot;任何人都能用的高效工具&quot;。</p><hr><h2 id="七、本节的-动手体验" tabindex="-1">七、本节的&quot;动手体验&quot; <a class="header-anchor" href="#七、本节的-动手体验" aria-label="Permalink to &quot;七、本节的&quot;动手体验&quot;&quot;">​</a></h2><p>现在轮到你亲自试试了。</p><p><strong>任务</strong>：让你的 Codex 帮你做一件小事。</p><ol><li>打开 Codex</li><li>输入以下任意一个指令（选一个你觉得有用的）： <ul><li>&quot;帮我写一封邮件，感谢客户昨天的订单&quot;</li><li>&quot;帮我列一个本周工作计划的模板&quot;</li><li>&quot;帮我生成一个待办事项清单的 HTML 页面&quot;</li></ul></li><li>看看 Codex 给出的结果</li><li>如果不够满意，试着追加一句要求，比如&quot;把语气改得更正式一些&quot;</li></ol><blockquote><p>💡 <strong>提示</strong>：不用追求完美结果。这一节的目标是让你感受&quot;用自然语言指挥 AI&quot;的体验。</p></blockquote><hr><h2 id="八、本节小结" tabindex="-1">八、本节小结 <a class="header-anchor" href="#八、本节小结" aria-label="Permalink to &quot;八、本节小结&quot;">​</a></h2><table tabindex="0"><thead><tr><th>能力类别</th><th>典型场景</th></tr></thead><tbody><tr><td>编程开发</td><td>写功能、修 Bug、重构代码</td></tr><tr><td>办公提效</td><td>整理资料、生成内容、做 PPT</td></tr><tr><td>数据分析</td><td>自动化处理数据、生成报告</td></tr><tr><td>日常任务</td><td>整理文件、分析磁盘空间、翻译文档</td></tr></tbody></table><p><strong>核心认知</strong>：Codex 不是一个&quot;高级搜索工具&quot;，它是一个能直接操作你文件和系统的&quot;智能助手&quot;。</p><hr><h2 id="九、课后思考" tabindex="-1">九、课后思考 <a class="header-anchor" href="#九、课后思考" aria-label="Permalink to &quot;九、课后思考&quot;">​</a></h2><ol><li>今天展示的哪个案例最让你觉得&quot;这对我有用&quot;？</li><li>你目前的工作中，有哪些重复性任务可以考虑交给 Codex？</li><li>你觉得 Codex 能帮你解决的最大痛点是什么？</li></ol><blockquote><p>💡 提示：带着这些问题进入下一节课，我们会对比 Codex 和其他工具的区别，帮你更清楚地定位它的价值。</p></blockquote><hr><h2 id="十、下一步" tabindex="-1">十、下一步 <a class="header-anchor" href="#十、下一步" aria-label="Permalink to &quot;十、下一步&quot;">​</a></h2><p><a href="./lesson-3.html">→ 第 3 课：Codex vs 其他工具</a></p>',86)])])}const g=t(l,[["render",i]]);export{p as __pageData,g as default};
